import{K as l,a as i,c as r,b as a,k as c,q as s,ac as n}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"Excel 查找匹配：XLOOKUP、VLOOKUP 与 INDEX MATCH","description":"按产品和编号匹配数据，理解精确匹配、缺失与重复键，使用 XLOOKUP、兼容旧版的 VLOOKUP 和 INDEX MATCH，并核对文本数字类型。","frontmatter":{"title":"Excel 查找匹配：XLOOKUP、VLOOKUP 与 INDEX MATCH","description":"按产品和编号匹配数据，理解精确匹配、缺失与重复键，使用 XLOOKUP、兼容旧版的 VLOOKUP 和 INDEX MATCH，并核对文本数字类型。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · Excel 表格与数据分析","summary":"按产品和编号匹配数据，理解精确匹配、缺失与重复键，使用 XLOOKUP、兼容旧版的 VLOOKUP 和 INDEX MATCH，并核对文本数字类型。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":{"text":"Excel 条件判断、计数与汇总","link":"/tools/office/excel/aggregate"},"next":{"text":"Excel 文本清洗、日期与时间计算","link":"/tools/office/excel/text-date"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Excel 条件判断、计数与汇总","link":"/tools/office/excel/aggregate"},"next":{"text":"Excel 文本清洗、日期与时间计算","link":"/tools/office/excel/text-date"}},"headers":[],"relativePath":"tools/office/excel/lookup.md","filePath":"tools/office/excel/lookup.md"}'),d={name:"tools/office/excel/lookup.md"},k=Object.assign(d,{setup(h){const t={path:"/tools/office/excel/lookup",app:"Excel",title:"按产品查价并发现缺失与重复",steps:[{tab:"工作表标签",command:"加号",setting:"工作表：产品；区域：A1:B4",anchor:"walkthrough-1",surface:"area"},{tab:"公式",command:"插入函数",setting:"函数：XLOOKUP；匹配方式：0",anchor:"walkthrough-2"},{tab:"数据",command:"筛选",setting:"检查：未找到 / 重复键 / 非零差额",anchor:"walkthrough-3"}]};return(p,e)=>{const o=l("OfficeGuide");return i(),r("div",null,[e[0]||(e[0]=a("h1",{id:"excel-查找匹配-xlookup、vlookup-与-index-match",tabindex:"-1"},[c("Excel 查找匹配：XLOOKUP、VLOOKUP 与 INDEX MATCH "),a("a",{class:"header-anchor",href:"#excel-查找匹配-xlookup、vlookup-与-index-match","aria-label":'Permalink to "Excel 查找匹配：XLOOKUP、VLOOKUP 与 INDEX MATCH"'},"​")],-1)),e[1]||(e[1]=a("p",null,"查找解决“按同一个标识从另一张表取值”。先确认匹配键唯一且类型一致，再选择函数；看起来成功返回一个值，不代表选中了正确记录。",-1)),s(o,{guide:t}),e[2]||(e[2]=n(`<h2 id="data" tabindex="-1">建立产品表 <a class="header-anchor" href="#data" aria-label="Permalink to &quot;建立产品表 {#data}&quot;">​</a></h2><p>新建 <code>产品</code> 工作表，在 A1:B4 输入：</p><table tabindex="0"><thead><tr><th>产品</th><th style="text-align:right;">单价</th></tr></thead><tbody><tr><td>键盘</td><td style="text-align:right;">120</td></tr><tr><td>鼠标</td><td style="text-align:right;">80</td></tr><tr><td>显示器</td><td style="text-align:right;">900</td></tr></tbody></table><p>在 <code>订单</code> 的独立检查列查出价格，与原单价比较，不直接覆盖原始数据。真实业务往往应按产品编码匹配，产品名称可能重名或改名；本练习只为演示函数而使用唯一名称。</p><h2 id="xlookup" tabindex="-1">使用 XLOOKUP <a class="header-anchor" href="#xlookup" aria-label="Permalink to &quot;使用 XLOOKUP {#xlookup}&quot;">​</a></h2><p>从订单第 2 行的 D2 产品查价格：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=XLOOKUP(D2,产品!$A$2:$A$4,产品!$B$2:$B$4,&quot;未找到&quot;,0)</span></span></code></pre></div><p>参数依次是查找值、查找区域、返回区域、缺失结果、匹配方式。<code>0</code> 明确表示精确匹配，XLOOKUP 默认也是精确匹配；返回区域可位于查找列左侧。向下填充时，D2 随行移动，产品表的范围保持锁定。</p><p>XLOOKUP 不适用于 Excel 2016、2019；即使这些版本能打开别人创建的文件，也不等于能正确计算这个函数。旧版使用下面的替代公式。<a href="https://support.microsoft.com/en-us/excel/functions/xlookup-function" target="_blank" rel="noopener noreferrer">微软 XLOOKUP 说明</a></p><h2 id="legacy" tabindex="-1">使用 VLOOKUP 与 INDEX MATCH <a class="header-anchor" href="#legacy" aria-label="Permalink to &quot;使用 VLOOKUP 与 INDEX MATCH {#legacy}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=VLOOKUP(D2,产品!$A$2:$B$4,2,FALSE)</span></span>
<span class="line"><span>=INDEX(产品!$B$2:$B$4,MATCH(D2,产品!$A$2:$A$4,0))</span></span></code></pre></div><p>VLOOKUP 在指定区域的第一列找值，从区域第 2 列返回结果，<code>FALSE</code> 表示精确匹配。遗漏最后一个参数可能进入近似匹配，未满足排序等条件时结果容易出错。INDEX MATCH 中，MATCH 先找位置，再由 INDEX 从价格区域取对应位置。</p><p>需要处理查找不到的情况时，可以使用 <code>IFNA(公式,&quot;未找到&quot;)</code>，保持其他计算错误可见。不要把缺失价格默认为零，零可能被误当成免费产品，从而影响金额汇总。</p><h2 id="quality" tabindex="-1">重复键与类型问题 <a class="header-anchor" href="#quality" aria-label="Permalink to &quot;重复键与类型问题 {#quality}&quot;">​</a></h2><p>在产品表第 5 行增加第二个“鼠标”且价格不同，把查找公式的产品范围扩展到 A2:A5、价格范围扩展到 B2:B5。普通精确查找通常只返回某个匹配位置，不能自动判断哪个有效。用 <code>COUNTIF(产品!$A$2:$A$5,D2)</code> 检查匹配数量；等于 0 是缺失，大于 1 是重复，需要清理或增加版本、日期等匹配条件。新增记录后不扩大固定范围，查找和检查都会遗漏新行。</p><p>编号 <code>00123</code> 与数值 123 可能不是同一种键。去掉前导零前先确认业务是否允许；给长编号转换为数值还可能丢失精度。字符串中的前后空格、不间断空格和全角字符也可能造成看起来相同但匹配不到。</p><h2 id="arrays" tabindex="-1">新版筛选函数 <a class="header-anchor" href="#arrays" aria-label="Permalink to &quot;新版筛选函数 {#arrays}&quot;">​</a></h2><p>需要取出所有匹配记录时，单值查找并不合适。支持动态数组的版本可在空白普通区域输入：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=FILTER(Sales,Sales[部门]=&quot;运营&quot;,&quot;无记录&quot;)</span></span></code></pre></div><p>结果会溢出为多行多列，周围必须有空位，不能把这类溢出公式放在 Excel 表格内部当作整块输出。缺少 FILTER 的旧版可使用自动筛选、辅助列或 Power Query，不能只修改扩展名解决功能缺失。</p><h2 id="practice" tabindex="-1">练习与验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;练习与验收 {#practice}&quot;">​</a></h2><p>依次查找键盘、鼠标、显示器，结果为 120、80、900；查找“耳机”应显示未找到。再制造一个重复产品名，确认检查列能提示重复。清理测试数据后，把查找价格与订单原价格相减，八行差值应全为 0。</p><h2 id="walkthrough" tabindex="-1">图示跟做：按产品查价并发现缺失与重复 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：按产品查价并发现缺失与重复 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：准备唯一且类型一致的键 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：准备唯一且类型一致的键 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：工作表标签 → 加号。</strong></p><p>新建产品工作表，按正文录入键盘 120、鼠标 80、显示器 900。产品名称只出现一次，价格列存数值。在订单副本 I1 写“查得单价”，先保留原单价 F 列作对照；查找结果不能未经核对就覆盖源数据。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：输入查找式并向下检查 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：输入查找式并向下检查 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：公式 → 插入函数。</strong></p><p>在 I2 输入正文的 XLOOKUP 公式，以 D2 查产品名，锁定产品表的 A2:A4、B2:B4。向下填充到 I9，再在 J2 输入 =I2-F2 并填充。八行差额应为 0。旧版找不到 XLOOKUP 时使用正文精确匹配的 VLOOKUP 或 INDEX MATCH，不能省略匹配条件。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：主动制造两种失败情况 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：主动制造两种失败情况 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：数据 → 筛选。</strong></p><p>在练习副本把一个产品改成耳机，确认得到“未找到”，而不是零元。再在产品表第 5 行新增另一条鼠标价格，扩展查找及 COUNTIF 的范围到第 5 行，匹配数应大于 1。查找能返回数值并不代表键唯一，必须先决定哪条产品记录有效。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>完成故障练习后恢复三条产品和原订单名称。若看似相同仍匹配不到，检查空格、全角字符与文本数字类型；含前导零的编码不能随意转数值。</p>`,35))])}}});export{g as __pageData,k as default};
